        foreach ($jgrpklas as $kgrpklas) {
            $data['klasifikasi'][$x]  =   $kgrpklas->klasifikasi;
            $x++;
        }
		if ($x == 0){
			$data['klasifs'][0][0]['jenis']	= 'Surat Dinas';
			$data['klasifs'][0][0]['kode']	= 'S';
			$data['klasifikasi'][0]         = 'Surat Dinas';
		}
		if (Session('fakultas') == 'DPM' AND Session('previlage') == 'Admin SDM'){
			$data['arrallpeg']  		= Simpegpegawai::where('ppabp', '!=', 'Rekrutmen PT DPM')->where('status_pegawai', '1')->get();
			$data['kelompokjabatan']  	= Kelompoklain::all();
			$data['pejabats']   		= Pejabatsurat::orderBy('id')->get();
		} else {
			$data['arrallpeg']  		= Simpegpegawai::where('ppabp', Session('fakpanjang'))->get();
			$data['kelompokjabatan']  	= Kelompoklain::where('fakultas', Session('fakpanjang'))->get();
			$data['pejabats']   		= Pejabatsurat::where('fakultas', Session('fakultas'))->orderBy('id')->get();
		}
		
		$data['arrsdomain']  			= DB::table('app_menu')->where('subdomainapps', '!=', 'RKTDPM')->get();
        $data['counttandatangan']  		= 0;
        $data['sountrungmari']  		= 0;
        $data['sountmari']  			= 0;
        $data['carinip']  				= 0;
        $data['sidebar']			   	= 'persuratanrs';
		return view('persuratan.rs', $data);
    }
	public function pleaseSignberkas($id){
		$homebase	= url("/");
		$alamatweb	= $homebase.'/viewsurat/'.$id;
		$qrcode 	= QrCode::size(80)->generate($alamatweb);
		$kalender   = array('wulan','Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember');
		$dd         = date("d");
		$mm         = (int)date("m");
		$mm			= $kalender[$mm];
		$tahuniki   = date("Y");
		$tglsurat	= date("Y-m-d");
		$sakniki	= $dd.' '.$mm.' '.$tahuniki;
		$getarrsurat= explode("-",$id);
		if (isset($getarrsurat[1])){
			$id				= $getarrsurat[1];
			$rom  			= Suratkeluar::where('id', $id)->first();
			if (isset($rom->id)){
				$status 	= $rom->status;
				$arsip 		= $rom->arsip;
				$lampiran	= $rom->lampiran;
				$cekdata	= User::where('email', $rom->alamat)->first();
				if (isset($cekdata->id)){
					$tandatangan = $cekdata->tandatangan;
				} else {
					$tandatangan = '';
				}
				if ($rom->filelampiran != ''){
					$alamatweb	= $homebase.'/viewsurat/keluar-'.$rom->id;
					return Redirect::to($alamatweb);
				} else {
					$alamatweb				= 	$homebase.'/viewsurat/keluar-'.$rom->id;
					$data           		=   [];
					$data['jenissurat'] 	= 	'Surat Keluar';
					$data['tandatangan'] 	= 	$tandatangan;
					$data['idsurat'] 	    = 	$id;
					$data['sakniki']       	=   $sakniki;
					$data['alamatweb']    	=   $alamatweb;
					$data['surat']     		=   $rom;
					return view('bantuan.formttd', $data);
				}
			} else {
				$data['judulpesan']			= 'Files is Missing';
				$data['kalimatheader']		= 'Surat Keluar Dengan ID '.$id.' Tidak ditemukan';
				$data['kalimatbody']		= 'Silahkan Periksa Kembali URL Anda, dan Apabila errors seperti ini berlanjut coba refresh laman anda atau hubungi tim IT Terkait. Mohon Maaf <br /> <a href="/">Kembali Ke Laman Awal</a>';
				return view('errors.pesanerror', $data);
			}
		} else {
			$data['judulpesan']			= 'Unkown Errors';
			$data['kalimatheader']		= 'Jenis Tracking Belum Di Tentukan';
			$data['kalimatbody']		= 'Silahkan Periksa Kembali URL Anda, dan Apabila errors seperti ini berlanjut coba refresh laman anda atau hubungi tim IT Terkait. Mohon Maaf <br /> <a href="/">Kembali Ke Laman Awal</a>';
			return view('errors.pesanerror', $data);
		}
	}
